function validate([n, quantities]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is an integer between 1 and 10^5.';
  if (!Array.isArray(quantities) || quantities.length < 1) return 'quantities needs at least one value.';
  if (quantities.length > n) return 'There are at most n product kinds (m <= n).';
  if (quantities.some(q => !Number.isInteger(q) || q < 1 || q > 100000)) return 'Each quantity is an integer between 1 and 10^5.';
  return null;
}

