function minimizedMaximum(n, quantities) {
  let left = 1;
  let right = Math.max(...quantities);

  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    let stores = 0;
    for (const quantity of quantities) {
      stores += Math.ceil(quantity / mid);
    }
    if (stores <= n) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  return left;
}

