function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const m = int(1, 5);
    const n = m + int(0, 8);
    const top = rand() < 0.8 ? int(1, 25) : 300;
    return [n, Array.from({ length: m }, () => int(1, top))];
  }
  const m = int(1000, 2000);
  const shape = int(0, 2);
  const n = shape === 0 ? m + int(0, 50) : shape === 1 ? int(m, 100000) : 100000;
  return [n, Array.from({ length: m }, () => int(1, 100000))];
}
